import {Component, Input, OnInit} from '@angular/core';
import {CommonModule} from '@angular/common';
import {FormsModule} from '@angular/forms';
import {Club} from '../../models/club.model';
import {Venue} from '../../models/venue.model';
import {TvzApiService} from '../../services/tvz-api.service';

@Component({
  selector: 'app-search-club-venue',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './search-club-venue.component.html'
})
export class SearchClubVenueComponent implements OnInit {
  searchTerm = '';
  showDropdown = false;
  clubs: Club[] = [];
  clubMap: Map<number, Club> = new Map();
  venues: Venue[] = [];
  venueMap: Map<number, Venue> = new Map();
  clubResults: number[] = [];
  venueResults: number[] = [];
  selectedClubId: number | undefined;
  selectedVenueId: number | undefined;
  placeholder = ''

  @Input() searchMode: 'both' | 'club' | 'venue' = 'both';
  @Input() showSelection = true;
  @Input() callback?: (data?: { club?: Club; venue?: Venue }) => void;

  constructor(private api: TvzApiService) {
  }

  ngOnInit() {
    if (this.searchMode === 'club' || this.searchMode === 'both') {
      this.loadClubs()
    }
    if (this.searchMode === 'venue' || this.searchMode === 'both') {
      this.loadVenues()
    }
    if (this.searchMode === 'club') {
      this.placeholder = 'Suche nach Verein';
    } else if (this.searchMode === 'venue') {
      this.placeholder = 'Suche nach Halle';
    } else {
      this.placeholder = 'Suche nach Verein oder Halle';
    }
  }

  loadClubs() {
    this.api.getClubs().subscribe(allClubs => {
      this.clubs = allClubs;
      this.clubMap = new Map(allClubs.map(club => [club.clubId, club]));
      this.updateSearchIndex();
    })
  }

  loadVenues() {
    this.api.getVenues().subscribe(allVenues => {
      this.venues = allVenues;
      this.venueMap = new Map(allVenues.map(v => [v.venueId, v]));
      this.updateSearchIndex();
    });
  }

  updateSearchIndex() {
    const searchTermLower = this.searchTerm.toLowerCase();
    const clubIds = new Set<number>();
    const venueIds = new Set<number>();

    if (this.searchMode === 'club' || this.searchMode === 'both') {
      for (const club of this.clubs) {
        if (club.clubName.toLowerCase().includes(searchTermLower)) {
          clubIds.add(club.clubId);
        }
      }
      this.clubResults = Array.from(clubIds);
    }
    if (this.searchMode === 'venue' || this.searchMode === 'both') {
      for (const venue of this.venues) {
        if (venue.venueName.toLowerCase().includes(searchTermLower) ||
          venue.venueCity.toLowerCase().includes(searchTermLower)) {
          venueIds.add(venue.venueId);
        }
      }
      this.venueResults = Array.from(venueIds);
    }
  }

  activateDropDown() {
    this.showDropdown = true;
  }

  selectClub(clubId: number) {
    this.showDropdown = false;
    if (this.selectedClubId === clubId) {
      this.selectedClubId = undefined;
    } else {
      this.selectedClubId = clubId;
    }
    this.callback?.({club: this.clubMap.get(clubId)});
  }

  selectVenue(venueId: number) {
    this.showDropdown = false;
    if (this.selectedVenueId === venueId) {
      this.selectedVenueId = undefined;
    } else {
      this.selectedVenueId = venueId;
    }
    this.callback?.({venue: this.venueMap.get(venueId)});
  }

  clearClubSelection() {
    this.selectedClubId = undefined;
    this.callback?.({club: undefined});
  }

  clearVenueSelection() {
    this.selectedVenueId = undefined;
    this.callback?.({venue: undefined});
  }

  getVenueName(venueId: number): string {
    const venue = this.venueMap.get(venueId);
    if (venue) {
      return `${venue.venueName} (${venue.venueCity})`;
    }
    return '';
  }

  getClubName(clubId: number): string {
    return this.clubMap.get(clubId)?.clubName ?? '';
  }

  isSelectedClub(clubId: number): boolean {
    return this.selectedClubId === clubId;
  }

  isSelectedVenue(venueId: number): boolean {
    return this.selectedVenueId === venueId;
  }
}
