import {inject, Injectable} from '@angular/core';
import {BehaviorSubject} from 'rxjs';
import {ToastService} from './toast.service';
import {LoggerService} from './logger.service';

@Injectable({ providedIn: 'root' })
export class GeolocationService {
  toast = inject(ToastService);
  geolocationStatus: 'granted' | 'denied' | 'unknown' = 'unknown';
  userLocation: { lat: number; lon: number } | undefined;
  userLocationName: string | undefined;
  locationAllowed$ = new BehaviorSubject<boolean>(false);
  private watchId: number | null = null;

  constructor(private log: LoggerService) {}

  startTracking(callback: (position?: GeolocationPosition, error?: GeolocationPositionError) => void): void {
    if ('geolocation' in navigator) {
      this.watchId = navigator.geolocation.watchPosition(
        position => {
          this.geolocationStatus = 'granted';
          if (!this.locationAllowed$.getValue()) {
            this.locationAllowed$.next(true);
          }
          callback(position)
        },
        error => {
          if (this.locationAllowed$.getValue()) {
            this.locationAllowed$.next(false);
          }
          this.locationAllowed$.next(false);
          this.toast.add('Fehler','Ortungsdienste sind blockiert. Bitte in Einstellungen anpassen und erneut prüfen.', "error");
          this.geolocationStatus = 'denied';
          callback(undefined, error);
        },
        { enableHighAccuracy: true, maximumAge: 10000, timeout: 5000 }
      );
    } else {
      this.geolocationStatus = 'denied';
    }
  }

  stopTracking(): void {
    if (this.watchId !== null) {
      navigator.geolocation.clearWatch(this.watchId);
      this.watchId = null;
    }
  }

  getDistance(a: { lat: number; lon: number }, b: { lat: number; lon: number }): number {
    const dx = a.lat - b.lat;
    const dy = a.lon - b.lon;
    return Math.sqrt(dx * dx + dy * dy) * 111;
  }

  loadLocationName(lat: number, lon: number) {
    const url = `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json`;

    fetch(url, {
      headers: { 'User-Agent': 'potm.ch' }  // freundlich bleiben :)
    })
      .then(res => res.json())
      .then(data => {
        this.userLocationName = data.address?.city || data.display_name;
      })
      .catch(err => {
        this.log.warn('Reverse-Geocoding fehlgeschlagen', err);
      });
  }
}
